head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf92000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf92000.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_modCnt", fn: function(){ return ((dma_reqCkMap.get("modCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.modCnt"); })()) > 0); } }, { id: "if_delCnt", fn: function(){ return ((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) > 0); } }, { id: "if_activYn", fn: function(){ return ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) === 'Y' && (dma_map.get("activTpCd") ?? (() => { throw new Error("unresolved:" + "map.activTpCd"); })()) === 'Y' && (dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) !== 'Y' && (dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) !== 'D'); } }, { id: "if_activYn", fn: function(){ return ((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) === 0  && (dma_reqCkMap.get("modCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.modCnt"); })()) === 0 && (dma_map.get("delYn") ?? (() => { throw new Error("unresolved:" + "map.delYn"); })()) !== 'Y'); } }, { id: "if_modCnt", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }, { id: "if_delCnt", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }, { id: "if_activYn", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_stdcdType", fn: function () { return String((dma_pageContext.get("stdcdType") ?? "")); } },
        { childId: "ipt_stdCd", fn: function () { return String((dma_pageContext.get("stdCd") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.setComma();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf92000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_goModify_onclick
 * @description btn_goModify 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goModify_onclick = async function(e){
    try {
        await scwin.go_modify()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf92000.btn_goModify_onclick' }); }
};

/**
 * @method
 * @name btn_goDelete_onclick
 * @description btn_goDelete 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goDelete_onclick = function(e){
    try {
        scwin.go_delete()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf92000.btn_goDelete_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf92000.btn_self_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setComma
 * @description set Comma 처리
 * @returns {void}
 * @hidden N
 */
scwin.setComma = function () {
    $c.util.getComponent('ipt_expPayAmt').setValue($c.num.formatNumber($c.util.getComponent('ipt_expPayAmt').getValue()));
    $c.util.getComponent('ipt_dcSales').setValue($c.num.formatNumber($c.util.getComponent('ipt_dcSales').getValue()));
    $c.util.getComponent('txt_expPayAmtTd').setLabel($c.util.getComponent('ipt_expPayAmt').getValue());
    $c.util.getComponent('txt_dcSalesTd').setLabel($c.util.getComponent('ipt_dcSales').getValue());
};

/**
 * @method
 * @name open_modify
 * @description open modify 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_modify = function () {
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF92000 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("mod");
    fn_passwordWin(form);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_passwordWin — JSP 팝업(window.open+폼 제출 — 회신)
};

/**
 * @method
 * @name open_delete
 * @description open delete 처리
 * @returns {void}
 * @hidden N
 */
scwin.open_delete = function () {
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF92000 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("del");
    fn_passwordWin(form);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_passwordWin — JSP 팝업(window.open+폼 제출 — 회신)
};

/**
 * @method
 * @name go_modify
 * @description go modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.go_modify = async function () {
    const fm = (document.JLDINF92000 || { elements: [] });
    const url = "/stdcd/stdcdModify.do?method=stdcdModify&type=7&std_cd=" + $c.util.getComponent('ipt_stdCd').getValue();
    fm.action = url;
    fm.target = "_top";
    await moveUrl(url, {});
};

/**
 * @method
 * @name go_delete
 * @description go delete 처리
 * @returns {void}
 * @hidden N
 */
scwin.go_delete = function () {
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF92000 || { elements: [] });
    fn_stdCdDelWin(form);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_stdCdDelWin — JSP 팝업(window.open+폼 제출 — 회신)
    $c.win.closePopup();
};
